import client from "../client";

const employeesAction = (data) => {

    return client.post("/employees/", data);

};
const employeesActionAdmin = (data) => {

    return client.post("/employees/admin", data);

};
const employeesActionJoint = (data) => {

    return client.post("/employees/joint", data);

};

export default {
    employeesAction,
    employeesActionAdmin,
    employeesActionJoint
};
