import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea } from "@heroui/react";
import { Loading } from '../../../components';
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";

import { ToastContainer, toast } from "react-toastify";
import formulationsApi from "../../../api/drugs/formulationsApi";
import departmentsApi from "../../../api/departmentsApi";


export default function DepartmentsFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();

    const [department, setDepartment] = useState(item ? item : null)

    const [errors, setErrors] = useState();
    const departmentsActionsApi = useApi(departmentsApi.departmentsAction);

    const handleDepartmentAction = async (data) => {
        const result = await departmentsActionsApi.request(data);

        if (result.ok) {
            setUpdated(true)
            setopenEditModal(setUpdated)
        } else {
            setUpdated(false)
        }

    }

    useEffect(() => { }, [department])

    useEffect(() => {

        if (departmentsActionsApi.data) {
            if (departmentsActionsApi.data.category) {
                setDepartment(departmentsActionsApi.data.category)
            }
        }
    }, [departmentsActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            title: department ? department.title : '',
            description: department ? department.description : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            if (item) {

                handleDepartmentAction({
                    "action": "UpdateDepartment",
                    "department_details": {
                        "id": department.id,
                        "title": values.title,
                        "description": values.description ? values.description : '',
                    }
                })
            } else {
                handleDepartmentAction({
                    "action": "CreateDepartment",
                    "department_details": {
                        "title": values.title,
                        "description": values.description


                    }

                })
            }




            resetForm();
        },
    });


    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {departmentsActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <Input
                                        id="title"
                                        name="title"
                                        autoFocus
                                        label="Title"
                                        placeholder="Enter title"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                    />

                                    <Textarea
                                        id="description"
                                        key="description"
                                        name="description"
                                        label="Description"
                                        placeholder="Type description"
                                        variant="bordered"
                                        defaultValue={formik.values.description}
                                        value={formik.values.description}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />
                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
