import React, { useEffect, useState } from 'react'
import DepartmentsTable from './DepartmentsTable'

import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import entitiesApi from '../../../api/entitiesApi';
import { getLoggedInUser } from '../../../helpers/authUtils';
import DepartmentsFormModal from './DepartmentsFormModal';
import { Divider } from "@heroui/react";
import employeesApi from '../../../api/employees/employeesApi';
import departmentsApi from '../../../api/departmentsApi';
import { Loading } from '../../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },

    { name: "Actions", uid: "actions" },
];


function DepartmentsList() {

    const [openDepartmentFormModal, setopenDepartmentFormModal] = useState(false)
    const navigate = useNavigate()
    const [entity, setEntity] = useState()
    const [departments, setDepartments] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const departmentsActionsApi = useApi(departmentsApi.departmentsAction)

    const [user, setUser] = useState()



    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

    const getEntityDepartments = async (user) => {
        setDepartments([])
        await departmentsActionsApi.request({
            "action": "GetEntityDepartments",
            "entity": user.entity_id
        })
    }



    useEffect(() => {
        console.log("")

        if (user) {

            getEntityDepartments(user)
        }


    }, [user])

    useEffect(() => {
        console.log("")

        if (user) {

            getEntityDepartments(user)
        }


    }, [openDepartmentFormModal])


    const handleEditAction = (item) => {

        setopenDepartmentFormModal(true)

        // setUpdated(false)

        setEntity(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {


        setopenDepartmentFormModal(true)

        setUpdated(false)

        setmodalTitle("Add new department")
        setEntity(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/retailers/departments/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/retailers/departments/delete/${item.id}`)
    }


    useEffect(() => {

        if (departmentsActionsApi.data && departmentsActionsApi.data.length) {

            setDepartments(departmentsActionsApi.data)
        }

        console.log('entitiesActionsApi.data', departmentsActionsApi.data)
    }, [departmentsActionsApi.data])

    useEffect(() => {

    }, [openDepartmentFormModal])

    //Filtering data
    useEffect(() => {
        setdata(departments)
    }, [departments])


    const handleFilter = (e) => {


        const search_param = e

        if (departments && departments.length > 0 && search_param && search_param !== '') {
            setdata(departments.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(departments);
        }

    };

    return departmentsActionsApi.loading ? <Loading loading={departmentsActionsApi.loading} /> : (
        <div>

            {openDepartmentFormModal && <DepartmentsFormModal openEditModal={openDepartmentFormModal} setopenEditModal={setopenDepartmentFormModal} item={entity} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <DepartmentsTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default DepartmentsList